application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #f3f6fb;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
}

.page-shell {
  width: min(100% - 2rem,  fiftyrem);
  max-width: 50rem;
  margin: 0 auto;
  padding: 2.5rem 0 3rem;
}

.quiz-header,
.result,
.question-card {
  background: #fff;
  border: 1px solid #d7deea;
  border-radius: 0.75rem;
  box-shadow: 0 0.2rem 0.8rem rgb(22 40 73 / 8%);
}

.quiz-header {
  padding: 1.5rem;
  margin-bottom: 1rem;
}

.eyebrow {
  color: #2459a6;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin: 0 0 0.35rem;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  font-size: clamp(1.8rem, 5vw, 2.5rem);
  margin-bottom: 0.5rem;
}

.quiz-header p:last-child {
  margin-bottom: 0;
}

.question-card {
  min-width: 0;
  margin: 1rem 0;
  padding: 1.25rem;
}

legend {
  font-size: 1.1rem;
  font-weight: 700;
  padding: 0;
  width: 100%;
}

.question-number {
  align-items: center;
  background: #2459a6;
  border-radius: 50%;
  color: #fff;
  display: inline-flex;
  height: 1.8rem;
  justify-content: center;
  margin-right: 0.4rem;
  width: 1.8rem;
}

.options {
  display: grid;
  gap: 0.65rem;
  margin-top: 1rem;
}

.option {
  align-items: center;
  border: 1px solid #aebbd0;
  border-radius: 0.45rem;
  cursor: pointer;
  display: flex;
  gap: 0.65rem;
  padding: 0.75rem;
}

.option:hover,
.option:has(input:checked) {
  background: #edf4ff;
  border-color: #2459a6;
}

.option input {
  accent-color: #2459a6;
  height: 1.1rem;
  width: 1.1rem;
}

.option:focus-within {
  outline: 3px solid #f4a623;
  outline-offset: 2px;
}

.error-message {
  color: #a32626;
  font-weight: 600;
  margin: 0.6rem 0 0;
  min-height: 1.5em;
}

.actions {
  margin: 1.25rem 0;
}

button {
  background: #174783;
  border: 0;
  border-radius: 0.45rem;
  color: #fff;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  padding: 0.8rem 1.4rem;
}

button:hover {
  background: #103664;
}

button:focus-visible {
  outline: 3px solid #f4a623;
  outline-offset: 3px;
}

.form-message {
  color: #a32626;
  font-weight: 600;
  min-height: 1.5em;
}

.result {
  padding: 1.25rem;
  text-align: center;
}

.result h2 {
  font-size: 1.25rem;
  margin-bottom: 0.35rem;
}

.score {
  color: #174783;
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0;
}

@media (max-width:  treintarem) {
  .page-shell {
    padding-top: 1rem;
  }
}

application.javascript:
"use strict";

const ANSWERS = Object.freeze({
  "question-1": "mars",
  "question-2": "pacific",
  "question-3": "carbon-dioxide"
});

function getSelectedValue(questionName) {
  const selected = document.querySelector(`input[name="${questionName}"]:checked`);
  return selected ? selected.value : null;
}

function clearValidation() {
  document.querySelectorAll(".error-message").forEach((message) => {
    message.textContent = "";
  });
  document.getElementById("form-message").textContent = "";
}

function validateAnswers() {
  let firstMissing = null;
  Object.keys(ANSWERS).forEach((questionName, index) => {
    const selected = getSelectedValue(questionName);
    const error = document.getElementById(`${questionName}-error`);
    if (!selected) {
      error.textContent = "Please select an answer.";
      if (!firstMissing) {
        firstMissing = document.querySelector(`input[name="${questionName}"]`);
      }
    } else {
      error.textContent = "";
    }
  });
  return firstMissing;
}

function calculateScore() {
  return Object.entries(ANSWERS).reduce((score, [questionName, correctAnswer]) => {
    return score + (getSelectedValue(questionName) === correctAnswer ? 1 : 0);
  }, 0);
}

function displayScore(score) {
  const scoreElement = document.querySelector('[data-testid="quiz-score"]');
  scoreElement.dataset.score = String(score);
  scoreElement.textContent = `${score} out of 3`;
}

function handleSubmit(event) {
  event.preventDefault();
  clearValidation();
  const firstMissing = validateAnswers();
  if (firstMissing) {
    document.getElementById("form-message").textContent = "Complete all questions before submitting.";
    firstMissing.focus();
    return;
  }
  displayScore(calculateScore());
}

function initialiseQuiz() {
  const form = document.getElementById("quiz-form");
  form.addEventListener("submit", handleSubmit);
}

document.addEventListener("DOMContentLoaded", initialiseQuiz);
